/**
 * Section 2's measurement, read from generated data.
 *
 * `src/data/intervention.json` is packet P1's, generated by
 * `scripts/build_intervention.py`. This reads it and never writes a number.
 *
 * WHY THIS FILE EXISTS RATHER THAN THE PAGE READING THE JSON DIRECTLY.
 * Two of the things section 2 states are not fields, they are facts about the
 * whole set: that one component is ranked first by attribution on every
 * dimension, and how far the largest disagreement actually goes. Deriving those
 * in the page would put arithmetic over a 12x64 array in a template. Deriving
 * them here means the page renders values and this file is the only place that
 * counts anything, which is also the only way the count and the figure cannot
 * come apart.
 *
 * THESE NUMBERS CARRY A DOCUMENT AND A LINE, NOT AN EVIDENCE ID.
 * D-35: `meta.evidenceId` is null and every `components[].evidenceId` is null,
 * because this measurement predates the evidence store. The rho values carry
 * `spearmanRhoSource` and the headline carries `headline.meanRhoSource`, both
 * `{document, line}`. So section 2 renders a citation where another section
 * would render a provenance chip, and it renders it at the same weight rather
 * than tucking it into a caption. A number whose provenance is a file and a
 * line is not a number with worse provenance; it is a number whose provenance
 * is written down somewhere else, and hiding that is the only way to get it
 * wrong.
 *
 * The two ids the page used to cite, `ev:e04-fixture` and `ev:r4-run`, resolve
 * to nothing in `src/data/evidence-index.json`. Neither is a typo for a real
 * record: the fixture predates the store entirely. They are not repaired here
 * and they are not resolved here, because there is nothing to resolve them to.
 */

/* -------------------------------------------------------------------------
   Loading. Same mechanism as decomposition.ts and base/data.ts: a Vite glob,
   so a file that does not exist is absent from the map rather than a path that
   resolves one way in dev and another in build.
   ------------------------------------------------------------------------- */

const dataModules = import.meta.glob<{ default: unknown }>("../../data/*.json", {
  eager: true,
});

/** A document and a line, which is what D-35 citations are made of. */
export interface DocSource {
  document: string;
  line: number;
}

export interface Component {
  id: string;
  type: string;
  attributionValue: number;
  patchEffect: number;
  /**
   * The patched component's effect as a multiple of the pair's own margin.
   * 1 means moving that one component moves the score by the entire distance
   * between the two answers.
   */
  patchFractionOfMargin: number | null;
  patchFractionOfMarginSigned: number | null;
  evidenceId: string | null;
  attributionRank: number;
  patchRank: number;
}

export interface Dimension {
  key: string;
  pairCount: number;
  spearmanRho: number;
  spearmanRhoSource: DocSource;
  topAttributionComponent: string;
  topPatchComponent: string;
  components: Component[];
}

export interface RawIntervention {
  headline: {
    meanRho: number;
    meanRhoSource: DocSource;
    sharpestDimension: string;
    sharpestRho: number;
    positiveDimensions: number;
    negativeDimensions: number;
  };
  meta: {
    subject: string;
    dimensionCount: number;
    patchedComponentCount: number;
    evidenceId: string | null;
  };
  dimensions: Dimension[];
}

const raw = (): RawIntervention | null => {
  const mod = dataModules["../../data/intervention.json"];
  return mod ? (mod.default as RawIntervention) : null;
};

/** The single largest disagreement in the set, stated at its true size. */
export interface WidestMove {
  dimension: string;
  component: string;
  /** As a multiple of the margin. 7.71 is 771% of it. */
  fractionOfMargin: number;
  attributionRank: number;
  patchRank: number;
}

export interface Correlation {
  meanRho: number;
  meanRhoSource: DocSource;
  sharpestRho: number;
  sharpestDimension: string;
  sharpestRhoSource: DocSource;
  positiveDimensions: number;
  negativeDimensions: number;
  subject: string;
  dimensions: Dimension[];
  /** The component ranked first by attribution, when it is the same one throughout. */
  topAttributionComponent: string | null;
  /** How many dimensions rank that component LAST by patching. */
  topAttributionRankedLastByPatching: number;
  patchedComponentCount: number;
  widestMove: WidestMove | null;
}

export const correlation = (): Correlation | null => {
  const d = raw();
  if (!d) return null;

  const sharpest = d.dimensions.find((x) => x.key === d.headline.sharpestDimension);
  if (!sharpest) {
    throw new Error(
      `home §2: intervention.json names "${d.headline.sharpestDimension}" as the ` +
        `sharpest dimension and carries no dimension with that key, so the figure ` +
        `and the sentence above it would disagree. Owner: packet P1.`,
    );
  }

  /* The component ranked first by attribution. Reported as a single name only
     when every dimension agrees on it, and null otherwise: "the top component"
     is a claim about the set, and it stops being true the moment one dimension
     disagrees. */
  const tops = new Set(d.dimensions.map((x) => x.topAttributionComponent));
  const topAttributionComponent = tops.size === 1 ? [...tops][0] : null;

  const last = d.meta.patchedComponentCount;
  const topAttributionRankedLastByPatching = topAttributionComponent
    ? d.dimensions.filter(
        (x) =>
          x.components.find((c) => c.id === topAttributionComponent)?.patchRank === last,
      ).length
    : 0;

  /* The largest single movement anywhere in the set. Scanned over every
     component of every dimension rather than over the one component the
     sentence happens to name: the biggest disagreement in the data is the
     honest size of the disagreement, and it is not necessarily the one that
     was noticed first. */
  let widestMove: WidestMove | null = null;
  for (const dim of d.dimensions) {
    for (const c of dim.components) {
      const f = c.patchFractionOfMargin;
      if (typeof f !== "number" || !Number.isFinite(f)) continue;
      if (!widestMove || Math.abs(f) > Math.abs(widestMove.fractionOfMargin)) {
        widestMove = {
          dimension: dim.key,
          component: c.id,
          fractionOfMargin: f,
          attributionRank: c.attributionRank,
          patchRank: c.patchRank,
        };
      }
    }
  }

  return {
    meanRho: d.headline.meanRho,
    meanRhoSource: d.headline.meanRhoSource,
    sharpestRho: d.headline.sharpestRho,
    sharpestDimension: d.headline.sharpestDimension,
    sharpestRhoSource: sharpest.spearmanRhoSource,
    positiveDimensions: d.headline.positiveDimensions,
    negativeDimensions: d.headline.negativeDimensions,
    subject: d.meta.subject,
    dimensions: d.dimensions,
    topAttributionComponent,
    topAttributionRankedLastByPatching,
    patchedComponentCount: last,
    widestMove,
  };
};
